  `source_aggregate_version` bigint(20) unsigned NOT NULL DEFAULT 0,
  `source_calendar_version` bigint(20) unsigned NOT NULL DEFAULT 0,
  `source_action` varchar(16) NOT NULL DEFAULT 'upsert',
